const body = $json.body || $json;

const requirement = body.requirement || {};
const aiInstruction = body.ai_instruction || {};

return [{
  json: {
    request_id: body.request_id || `reqjob_${Date.now()}`,
    automation_type: body.automation_type || 'generate_job_openings',
    callback_url: body.callback_url || null,
    authorization: body.authorization || body.auth_header || '',
    auth_header: body.auth_header || body.authorization || '',
    requirement,
    ai_instruction: aiInstruction,
    metadata: body.metadata || {},
    received_at: new Date().toISOString()
  }
}];

const original = $('Code - Extract Request Data').first().json;
const errorMsg = $json.error?.message || $json.message || 'AI generation or response parsing failed';

return [{
  json: {
    request_id: original.request_id,
    automation_type: original.automation_type || 'generate_job_openings',
    status: 'failed',
    requirement_id: original.requirement?.requirement_id || null,
    client_id: original.requirement?.client_id || null,
    error: {
      code: 'AI_GENERATION_FAILED',
      message: errorMsg
    },
    job_openings: [],
    errors: [{ message: errorMsg }]
  }
}];

const data = $('Code - Extract Request Data').first().json;
const missing = [];
if (!data.request_id) missing.push('request_id');
if (!data.requirement?.requirement_id) missing.push('requirement.requirement_id');
if (!data.requirement?.title) missing.push('requirement.title');
if (!data.requirement?.description) missing.push('requirement.description');
if (!data.requirement?.num_posts_requested) missing.push('requirement.num_posts_requested');

return [{
  json: {
    request_id: data.request_id || null,
    automation_type: data.automation_type || 'generate_job_openings',
    status: 'failed',
    requirement_id: data.requirement?.requirement_id || null,
    client_id: data.requirement?.client_id || null,
    error: {
      code: 'VALIDATION_FAILED',
      message: `Missing required field(s): ${missing.join(', ')}`
    },
    job_openings: []
  }
}];

const requirement = $json.requirement;
const aiInstruction = $json.ai_instruction || {};
const count = Math.max(1,Number(requirement.num_posts_requested || 1));
requirement.num_posts_requested = count;

const systemPrompt = `You are a professional recruitment assistant. Generate complete job opening drafts from recruitment requirements, including classification tags. You must return only valid JSON. No markdown. No explanations.`;

const userPrompt = `Generate job opening drafts from the given recruitment requirement.

Requirement:
${JSON.stringify(requirement, null, 2)}

Recruiter instruction:
${aiInstruction.instruction || 'No extra instruction provided.'}

Additional AI controls:
- Tone: ${aiInstruction.tone || 'professional'}
- Output language: ${aiInstruction.output_language || 'en'}
- Must include: ${(aiInstruction.must_include || []).join(', ') || 'None'}
- Avoid: ${(aiInstruction.avoid || []).join(', ') || 'None'}

Rules:
- Generate exactly ${count} job openings.
- Return ONLY valid JSON.
- Do not include markdown.
- Do not include explanation.
- Each job opening must be distinct if more than one is requested.
- Responsibilities must contain 6 to 8 items.
- Qualifications must contain 5 to 7 items.
- Keywords must contain 8 to 10 searchable keywords.
- If the requirement is vague, create realistic but not exaggerated job openings.
- Use Indian salary format when INR is provided.
- Assign a "category" tag: Must be exactly either "technical" or "non-technical".
- Assign a "sub_category" tag: E.g., "Sales", "Resource Management", or "Higher Management" for non-technical; and "CI/CD", "Full Stack", "Kotlin Specialist", or a similar specific technical domain/technology for technical.

Return this exact JSON structure:
{
  "job_openings": [
    {
      "post_index": 1,
      "title": "string",
      "description": "string",
      "responsibilities": ["string"],
      "qualifications": ["string"],
      "salary_range": "string",
      "keywords": ["string"],
      "category": "string ('technical' or 'non-technical')",
      "sub_category": "string"
    }
  ]
}`;

return [{
  json: {
    ...$json,
    expected_count: count,
    ai_system_prompt: systemPrompt,
    ai_user_prompt: userPrompt
  }
}];

const originalData = $('Code - Extract Request Data').first().json;
const aiOutput = $json.output || $json.text || $json.response || $json.message;

if (!aiOutput) {
  throw new Error('AI Agent returned empty output');
}

function parseJson(value) {
  if (typeof value === 'object' && value !== null) return value;

  let text = String(value || '').trim();
  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first >= 0 && last > first) {
    text = text.slice(first, last + 1);
  }

  return JSON.parse(text);
}

let parsed;
try {
  parsed = parseJson(aiOutput);
} catch (err) {
  return [{
    json: {
      request_id: originalData.request_id,
      automation_type: originalData.automation_type,
      status: 'failed',
      requirement_id: originalData.requirement.requirement_id,
      client_id: originalData.requirement.client_id,
      generated_count: 0,
      job_openings: [],
      errors: [{
        code: 'AI_JSON_PARSE_FAILED',
        message: err.message,
        raw_tail: String(aiOutput).slice(-500)
      }]
    }
  }];
}

if (!Array.isArray(parsed.job_openings)) {
  throw new Error('job_openings array missing');
}

const expectedCount = Number(originalData.requirement.num_posts_requested || parsed.job_openings.length || 1);

const normalizedOpenings = parsed.job_openings.slice(0, expectedCount).map((job, index) => {
  // Normalize and validate category
  let category = null;
  if (job.category && typeof job.category === 'string') {
    const cleanCategory = job.category.toLowerCase().trim();
    if (cleanCategory === 'technical' || cleanCategory === 'non-technical') {
      category = cleanCategory;
    }
  }

  return {
    job_opening_id: job.job_opening_id || `job_${originalData.requirement.requirement_id}_${index + 1}`,
    requirement_id: originalData.requirement.requirement_id,
    client_id: originalData.requirement.client_id,
    client_name: originalData.requirement.client_name || '',
    post_index: Number(job.post_index || index + 1),
    title: job.title || '',
    description: job.description || '',
    responsibilities: Array.isArray(job.responsibilities) ? job.responsibilities : [],
    qualifications: Array.isArray(job.qualifications) ? job.qualifications : [],
    salary_range: job.salary_range || '',
    keywords: Array.isArray(job.keywords) ? job.keywords : [],
    category: category,
    sub_category: (job.sub_category && typeof job.sub_category === 'string') ? job.sub_category.trim() : null,
    status: 'draft',
    processing_status: 'ready',
    source: 'ai',
    created_at: new Date().toISOString()
  };
});

return [{
  json: {
    request_id: originalData.request_id,
    automation_type: originalData.automation_type,
    status: 'success',
    requirement_id: originalData.requirement.requirement_id,
    client_id: originalData.requirement.client_id,
    generated_count: normalizedOpenings.length,
    processed_at: new Date().toISOString(),
    job_openings: normalizedOpenings,
    errors: []
  }
}];

const parsed = $('Code - Parse and Normalize AI Response1').first().json;
const staticData = $getWorkflowStaticData('global');
const storeKey = `job_generation_${parsed.request_id}`;

staticData[storeKey] = {
  request_id: parsed.request_id,
  inserted_rows: [],
  errors: []
};

return items;

const payload = $('Code - Parse and Normalize AI Response1').first().json;

if (payload.status !== 'success') {
  return [{ json: payload }];
}

return payload.job_openings.map(job => ({
  json: {
    request_id: payload.request_id,
    automation_type: payload.automation_type,
    requirement_id: payload.requirement_id,
    client_id: payload.client_id,
    generated_count: payload.generated_count,
    processed_at: payload.processed_at,

    job_opening_id: job.job_opening_id,
    requirement_id_insert: job.requirement_id,
    client_id_insert: job.client_id,
    post_index: job.post_index,
    title: job.title,
    description: job.description,
    responsibilities: job.responsibilities,
    qualifications: job.qualifications,
    salary_range: job.salary_range,
    keywords: job.keywords,
    category: job.category,
    sub_category: job.sub_category,
    status: job.status,
    processing_status: job.processing_status,
    source: job.source
  }
}));

const original = $json;
const staticData = $getWorkflowStaticData('global');

const key = original.request_id || 'default';
const storeKey = `job_generation_${key}`;

if (!staticData[storeKey]) {
  staticData[storeKey] = {
    request_id: original.request_id,
    inserted_rows: [],
    errors: [],
  };
}

staticData[storeKey].inserted_rows.push({
  id: original.id || null,
  job_opening_id: original.job_opening_id,
  requirement_id: original.requirement_id_insert,
  client_id: original.client_id_insert,
  post_index: original.post_index,
  title: original.title,
  description: original.description,
  responsibilities: original.responsibilities,
  qualifications: original.qualifications,
  salary_range: original.salary_range,
  keywords: original.keywords,
  category: original.category,
  sub_category: original.sub_category,
  status: original.status,
  processing_status: original.processing_status,
  source: original.source,
});

return items;

const parsed = $('Code - Parse and Normalize AI Response1').first().json;
const staticData = $getWorkflowStaticData('global');
const storeKey = `job_generation_${parsed.request_id}`;
const inserted = (staticData[storeKey] && staticData[storeKey].inserted_rows) || [];

const jobOpenings = inserted.length ? inserted : parsed.job_openings;

delete staticData[storeKey];

return [{
  json: {
    request_id: parsed.request_id,
    automation_type: parsed.automation_type,
    status: 'success',
    requirement_id: parsed.requirement_id,
    client_id: parsed.client_id,
    generated_count: jobOpenings.length,
    inserted_count: inserted.length,
    processed_at: parsed.processed_at,
    job_openings: jobOpenings,
    errors: []
  }
}];
